package oct6;

public class question2_IncreasingNumberTriangle {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num =5;
		for (int row =1;row<=num;row++)
		{
			for (int col=1;col<=row;col++)
			{
		
				System.out.print(col +" ");
			}
            System.out.println();

		}

	}

}
